SELECT s.Id,s.ProductAttributeCombinationId,s.SupplierId,s.StockQuantity,s.StockAvailabilityTypeId,s.OverriddenPrice,s.OverriddenPriceTorob,s.OldPrice,s.OldPriceStartDateUtc,s.OldPriceEndDateUtc,s.StoreDeliveryDeadlineDays,s.GuaranteeId,s.ProfitPercentage,s.FeePercentage,s.GoldAccessoriesPrice,s.GoldPricingProfileId,s.UseStoreGoldPrices,s.DeactivatedByGoldPriceUpdateFailure,s.OverriddenPriceInstallment,s.OverriddenPriceBuyNowPayLater,pv.Name AS SupplierName,pv.SystemName AS SupplierSystemName FROM SupplierProductAttributeCombination s JOIN Supplier pv ON pv.Id=s.SupplierId JOIN ProductAttributeCombination pac ON pac.Id=s.ProductAttributeCombinationId WHERE pac.ProductId IN (SELECT p.Id FROM Product p WHERE p.Published=1 AND p.Deleted=0 AND p.DisableBuyButton=0 AND p.CallForPrice=0 AND p.VisibleIndividually=1 AND EXISTS(SELECT 1 FROM ProductAttributeCombination pac WHERE pac.ProductId=p.Id AND pac.Deleted=0 AND pac.IsNotExist=0 AND pac.StockAvailabilityTypeId=20 AND pac.StockQuantity>0 AND pac.FinalPrice>0)) AND s.IsActive=1 AND s.Deleted=0 AND s.StockAvailabilityTypeId=20 AND s.StockQuantity>0 AND s.OverriddenPrice>0 AND pv.IsActive=1 AND pv.Deleted=0
